import org.apache.lucene.util.BytesRef;
import org.apache.lucene.util.IOUtils;

public class TestStringValueFacetCounts extends FacetTestCase {

  public void testBasicSingleValued() throws Exception {

    Directory dir = newDirectory();
    RandomIndexWriter writer = new RandomIndexWriter(random(), dir);

    Document doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("foo")));
    writer.addDocument(doc);

    doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("foo")));
    writer.addDocument(doc);

    doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("bar")));
    writer.addDocument(doc);

    doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("bar")));
    writer.addDocument(doc);

    doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("baz")));
    writer.addDocument(doc);

    Map<String, Integer> expectedCounts = Map.of("foo", 2, "bar", 2, "baz", 1);
    int expectedTotalDocCount = 5;

    IndexSearcher searcher = newSearcher(writer.getReader());
    writer.close();

    StringDocValuesReaderState state =
        new StringDocValuesReaderState(searcher.getIndexReader(), "field");
    checkTopNFacetResult(expectedCounts, expectedTotalDocCount, searcher, state, 10, 2, 1, 0);

    IOUtils.close(searcher.getIndexReader(), dir);
  }

  private void assertEmptyFacetResult(FacetResult result) {
    assertEquals(0, result.path.length);
    assertEquals(0, result.value);
    assertEquals(0, result.childCount);
    assertEquals(0, result.labelValues.length);
  }

  public void testEmptyMatchset() throws Exception {
    Directory dir = newDirectory();
    RandomIndexWriter writer = new RandomIndexWriter(random(), dir);

    Document doc = new Document();
    doc.add(new SortedSetDocValuesField("field", new BytesRef("foo")));
    writer.addDocument(doc);

    IndexSearcher searcher = newSearcher(writer.getReader());
    writer.close();

    FacetsCollector facetsCollector =
        searcher.search(new MatchNoDocsQuery(), new FacetsCollectorManager());
    StringDocValuesReaderState state =
        new StringDocValuesReaderState(searcher.getIndexReader(), "field");

    StringValueFacetCounts counts = new StringValueFacetCounts(state, facetsCollector);

    FacetResult top = counts.getTopChildren(10, "field");
    assertEmptyFacetResult(top);

    FacetResult all = counts.getAllChildren("field");
    assertEmptyFacetResult(all);

    assertEquals(0, counts.getSpecificValue("field", "foo"));

    IOUtils.close(searcher.getIndexReader(), dir);
  }

  // See: LUCENE-10070
  public void testCountAll() throws Exception {

    Directory dir = newDirectory();
    RandomIndexWriter writer = new RandomIndexWriter(random(), dir);

    Document doc = new Document();
    doc.add(new StringField("id", "0", Field.Store.NO));
    doc.add(new SortedSetDocValuesField("field", new BytesRef("foo")));
    writer.addDocument(doc);

    doc = new Document();
    doc.add(new StringField("id", "1", Field.Store.NO));
    doc.add(new SortedSetDocValuesField("field", new BytesRef("foo")));
    writer.addDocument(doc);

    doc = new Document();
    doc.add(new StringField("id", "2", Field.Store.NO));
    doc.add(new SortedSetDocValuesField("field", new BytesRef("bar")));
    writer.addDocument(doc);

    writer.deleteDocuments(new Term("id", "0"));

    IndexSearcher searcher = newSearcher(writer.getReader());
    writer.close();

    StringDocValuesReaderState state =
        new StringDocValuesReaderState(searcher.getIndexReader(), "field");

    StringValueFacetCounts facets = new StringValueFacetCounts(state);
    assertEquals(
        "dim=field path=[] value=2 childCount=2\n  bar (1)",
        facets.getTopChildren(1, "field").toString().trim());

    assertEquals(
        "dim=field path=[] value=2 childCount=2\n  bar (1)\n  foo (1)",
        facets.getTopChildren(10, "field").toString().trim());

    assertFacetResult(
        facets.getAllChildren("field"),
        "field",
        new String[0],
        2,
        2,
        new LabelAndValue[] {
          new LabelAndValue("bar", 1), new LabelAndValue("foo", 1),
        });

    IOUtils.close(searcher.getIndexReader(), dir);
  }

